func minInitialStrength(monsters []int, boosts [][]int) int64 {
	n := len(monsters)
	d := make([]int64, n+1)
	for _, b := range boosts {
		d[b[0]] += int64(b[2])
		d[b[1]+1] -= int64(b[2])
	}

	check := func(v int64) bool {
		var bonus int64
		for i, a := range monsters {
			bonus += d[i]
			if v+bonus < int64(a) {
				return false
			}
			v -= int64(a)
			if v < 0 {
				v = 0
			}
		}
		return true
	}

	var left, right int64 = 0, 1000000000000000
	for left < right {
		mid := (left + right) / 2
		if check(mid) {
			right = mid
		} else {
			left = mid + 1
		}
	}
	return left
}

function minInitialStrength(monsters: number[], boosts: number[][]): number {
    const n = monsters.length;
    const d = new Array<number>(n + 1).fill(0);

    for (const [l, r, v] of boosts) {
        d[l] += v;
        d[r + 1] -= v;
    }

    const check = (v: number): boolean => {
        let bonus = 0;
        for (let i = 0; i < n; i++) {
            bonus += d[i];
            if (v + bonus < monsters[i]) {
                return false;
            }
            v -= monsters[i];
            if (v < 0) {
                v = 0;
            }
        }
        return true;
    };

    let left = 0;
    let right = 1e15;
    while (left < right) {
        const mid = Math.floor((left + right) / 2);
        if (check(mid)) {
            right = mid;
        } else {
            left = mid + 1;
        }
    }
    return left;
}
